const cfg = $json;
const now = $now.setZone('Asia/Manila');
const today = now.toFormat('yyyy-MM-dd');
const destinations = JSON.parse(cfg.destinationsJson || '[]');
function deliveryFor(day) { const d = now.set({ day }); return d.weekday === 6 ? d.minus({ days: 1 }) : d.weekday === 7 ? d.minus({ days: 2 }) : d; }
const definitions = [
  { type: 'ten_customer_form', day: 5, label: 'Complete the 10-customer form' },
  { type: 'checks_deposits', day: 16, label: 'Complete checks and deposits' },
];
if (now.weekday === 1) definitions.push({ type: 'ro_group_report', day: now.day, label: 'Complete the weekly Monday RO group report' });
const due = definitions.filter((item) => deliveryFor(item.day).toFormat('yyyy-MM-dd') === today);
return due.flatMap((item) => destinations.map((destination) => ({ json: { ...cfg, reminderType: item.type, deadlineDate: now.set({ day: item.day }).toFormat('yyyy-MM-dd'), destinationKey: destination.key, chatId: destination.chatId, scheduledFor: now.toISO(), idempotencyKey: `${item.type}:${today}:${destination.key}`, telegramText: `UHP reminder: ${item.label}.` } })));
